package com.example.appointment.staff; import java.time.*; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface AvailabilityRepository extends JpaRepository<Availability,Long>{List<Availability> findByStaffIdOrderByDateAscStartTimeAsc(Long staffId); List<Availability> findByStaffIdAndDateOrderByStartTime(Long staffId,LocalDate date); boolean existsByStaffIdAndDateAndStartTimeLessThanAndEndTimeGreaterThan(Long id,LocalDate d,LocalTime end,LocalTime start);}
